        case 584: // Recognized '{Decimal}',	Shortest string "8.8"
        case 588: // Recognized '{Decimal}',	Shortest string "8.8_8"
        case 589: // Recognized '{Decimal}',	Shortest string "8_8e8"
yylval.s = StripDigitSeparators(yytext); return (int)Token.TFLOAT;
            break;
        case 594: // Recognized '{LineComment}',	Shortest string "--"
/* skip */
            break;
        case 595: // Recognized '{TJsonField}',	Shortest string "->"
return (int)Token.TJSONFIELD;
            break;
        case 596: // Recognized '{TJsonFieldText}',	Shortest string "->>"
return (int)Token.TJSONFIELDTEXT;
            break;
        case 597: // In <BLOCKCOMMENT> Recognized '\n',	Shortest string ""
/* skip newline in block comment */
            break;
        case 598: // In <BLOCKCOMMENT> Recognized '[^*\n]+',	Shortest string "-"
/* skip block comment body */
            break;
        case 599: // In <BLOCKCOMMENT> Recognized '"*"',	Shortest string "*"
/* lone star, not followed by slash */
            break;
        case 600: // In <BLOCKCOMMENT> Recognized '"*/"',	Shortest string "*/"
yy_pop_state();
            break;
        default:
            break;
    }
#pragma warning restore 162, 1522
#endregion
                    }
                }
        }

#if BACKUP
        void SaveStateAndPos(ref Context ctx) {
            ctx.bPos  = buffer.Pos;
            ctx.rPos  = readPos;
            ctx.cCol  = cCol;
            ctx.lNum  = lNum;
            ctx.state = state;
            ctx.cChr  = code;
        }

        void RestoreStateAndPos(ref Context ctx) {
            buffer.Pos = ctx.bPos;
            readPos = ctx.rPos;
            cCol  = ctx.cCol;
            lNum  = ctx.lNum;
            state = ctx.state;
            code  = ctx.cChr;
        }
#endif  // BACKUP

        // ============= End of the tokenizer code ================

#if STACK        
        [SuppressMessage("Microsoft.Performance", "CA1811:AvoidUncalledPrivateCode")]
        internal void yy_clear_stack() { scStack.Clear(); }
        
        [SuppressMessage("Microsoft.Performance", "CA1811:AvoidUncalledPrivateCode")]
        internal int yy_top_state() { return scStack.Peek(); }
        
        internal void yy_push_state(int state)
        {
            scStack.Push(currentScOrd);
            BEGIN(state);
        }
        
        internal void yy_pop_state()
        {
            // Protect against input errors that pop too far ...
            if (scStack.Count > 0) {
				int newSc = scStack.Pop();
				BEGIN(newSc);
            } // Otherwise leave stack unchanged.
        }
 #endif // STACK

        [SuppressMessage("Microsoft.Performance", "CA1811:AvoidUncalledPrivateCode")]
        internal void ECHO() { Console.Out.Write(yytext); }
        
    } // end class $Scanner


} // end namespace
